head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column8_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 아이템 리스트가 정상적으로 보여진다.a_name, b_name(이전에는 아이템 리스트가 보여지지 않음)
    // 1. The item list is displayed normally.a_name, b_name(Previously, the item list is not shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_customFilter_scrollView').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_customFilter_list').childNodes.length == 4", "true");
    WebSquare.wUnit.addCommand("assert", "document.querySelectorAll('.w2list_listRow.w2grid_customFilter_list_listRow')[2].innerText == 'a_name'", "true");
    WebSquare.wUnit.addCommand("assert", "document.querySelectorAll('.w2list_listRow.w2grid_customFilter_list_listRow')[3].innerText == 'b_name'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.j2 = [{
        "col1": "aa",
        "col2": "a_name"
    }, {
        "col1": "bb",
        "col2": "b_name"
    }];
    dataList2.setJSON(j2);
    window.j1 = [{
        "id1": "a1",
        "id2": "aa",
        "id3": "aa"
    }, {
        "id1": "b1",
        "id2": "bb",
        "id3": "bb"
    }];
    dataList1.setJSON(j1);
    WebSquare.wUnit.getObjById('gridView1').setColumnNodeSet("id3", "data:dataList2", "col2", "col1");
}
